import io
import json
import sqlite3
from pathlib import Path
from sync.client import VendorClient, http_get_json

requests = []
def fetch(url):
    requests.append(url)
    return http_get_json(url)

records = list(VendorClient(fetch_json=fetch, notices=io.StringIO()).iter_items())
conn = sqlite3.connect('data/catalog.db')
rows = {r[0]: r for r in conn.execute('SELECT * FROM products')}
before = {r[0]: tuple(r) for r in json.loads(Path('/tmp/catalog-before-sync.json').read_text())}
manual_before = {sku: row for sku, row in before.items() if row[3] == 'manual'}
manual_after = {sku: row for sku, row in rows.items() if row[3] == 'manual'}
assert manual_before == manual_after, 'Manual catalogue changed'
for record in records:
    sku = record['sku']
    if sku in manual_before:
        continue
    if record.get('deleted'):
        assert sku not in rows, f'Tombstone not applied: {sku}'
    else:
        row = rows[sku]
        assert row[1:4] == (record['name'], record['price_paise'], 'vendor'), sku
        if record.get('updated_at'):
            assert row[4] == record['updated_at'], sku
seen = {r['sku'] for r in records}
for sku in before.keys() - seen:
    assert rows[sku] == before[sku], f'Unmentioned SKU changed: {sku}'
assert conn.execute('PRAGMA integrity_check').fetchone() == ('ok',)
print(f'Verified {len(records)} feed records across {len(requests)} cursor pages.')
print(f'All {len(manual_before)} manual SKUs unchanged; {len(rows.keys() - seen)} unmentioned local SKUs retained.')
print('Database integrity: ok')
conn.close()
